import '@servicenow/sdk/global'
import { action, Flow, wfa } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// -----------------------------------------------------------------------------
// Flow definition that calls the Action
// -----------------------------------------------------------------------------
Flow(
    {
        $id: Now.ID['flow_object_example'],
        name: 'Flow - FlowObject Example',
        description: 'Calls action with FlowObject input/output',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_obj'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_t) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['act_inst_user_info'] },
            {
                log_level: 'info',
                log_message: 'Hello, World!',
            }
        )
    }
)
